function lcAudit(PDO $db,string $action,string $module,string $description,?string $type=null,?int $id=null):void{
 $q=$db->prepare("INSERT INTO audit_events(user_id,action,module_key,record_type,record_id,description,ip_address,user_agent) VALUES(?,?,?,?,?,?,?,?)");
 $q->execute([(int)($_SESSION['user_id']??0),$action,$module,$type,$id,$description,$_SERVER['REMOTE_ADDR']??null,substr((string)($_SERVER['HTTP_USER_AGENT']??''),0,255)]);
}
