<?php if($tab==='returns'&&$canReturn):?>
<section class="lc-panel"><h2>Record a sales return</h2><?php if($canReturnCreate):?><form method="post" class="lc-form"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="tab" value="returns"><input type="hidden" name="action" value="create_return"><label>Original sale item<select name="sale_item_id" required><option value="">Choose invoice / product</option><?php foreach($returnLines as $line):?><option value="<?=(int)$line['id']?>"><?=e($line['invoice_number'].' — '.$line['product_name'].' (sold '.$line['quantity'].')')?></option><?php endforeach;?></select></label><label>Quantity<input type="number" name="quantity" min="1" step="1" required></label><label>Refund method<select name="refund_method"><option>Cash</option><option>M-Pesa</option><option>Bank</option><option>Other</option></select></label><label>Reason<input name="reason" maxlength="500" required></label><label><span>Restock item</span><input type="checkbox" name="restock" value="1" checked></label><button class="lc-btn">Submit for approval</button></form><?php endif;?></section>
<section class="lc-panel"><h2>Return register</h2><table class="lc-table"><thead><tr><th>Return</th><th>Invoice</th><th>Date</th><th>Amount</th><th>Method</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($returns as $r):?><tr><td><?=e($r['return_number'])?></td><td><?=e($r['invoice_number'])?></td><td><?=e($r['return_date'])?></td><td>KES <?=number_format((float)$r['total_amount'],2)?></td><td><?=e($r['refund_method'])?></td><td><?=e($r['status'])?></td><td><?php if($r['status']==='Pending'&&$canReturnApprove):?><form method="post" class="inline"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="tab" value="returns"><input type="hidden" name="action" value="approve_return"><input type="hidden" name="return_id" value="<?=(int)$r['id']?>"><button class="lc-btn" name="decision" value="approve">Approve</button> <button class="lc-btn secondary" name="decision" value="reject">Reject</button></form><?php elseif($r['status']==='Approved'&&$canReturnApprove&&(float)$r['refund_due']>0):?><form method="post" class="lc-form"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="tab" value="returns"><input type="hidden" name="action" value="settle_return"><input type="hidden" name="return_id" value="<?=(int)$r['id']?>"><label>Refund amount<input type="number" name="amount" min="0.01" max="<?=e((string)$r['refund_due'])?>" step=".01" value="<?=e((string)$r['refund_due'])?>" required></label><label>Method<select name="payment_method"><option>Cash</option><option>M-Pesa</option><option>Bank</option><option>Other</option></select></label><label>Reference<input name="transaction_reference" maxlength="120"></label><button class="lc-btn">Record refund</button></form><?php else:?>—<?php endif;?></td></tr><?php endforeach;?></tbody></table></section>
<?php endif;?>
<?php if($tab==='shifts'&&$canCash):?>
<section class="lc-panel"><h2>Cashier shift</h2><?php if(!$openShift&&$canCashCreate):?><form method="post" class="lc-form"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="tab" value="shifts"><input type="hidden" name="action" value="open_shift"><label>Opening float (KES)<input type="number" name="opening_float" min="0" step=".01" value="0" required></label><button class="lc-btn">Open shift</button></form><?php elseif($openShift&&$canCashEdit):?><p>Open shift: <strong><?=e($openShift['shift_number'])?></strong> · Started <?=e($openShift['opened_at'])?> · Float KES <?=number_format((float)$openShift['opening_float'],2)?></p><form method="post" class="lc-form"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="tab" value="shifts"><input type="hidden" name="action" value="close_shift"><input type="hidden" name="shift_id" value="<?=(int)$openShift['id']?>"><label>Physically counted cash (KES)<input type="number" name="counted_cash" min="0" step=".01" required></label><label>Closing notes<input name="closing_notes" maxlength="1000"></label><button class="lc-btn">Close shift & reconcile</button></form><?php endif;?></section>
<section class="lc-panel"><h2>Shift register</h2><table class="lc-table"><thead><tr><th>Shift</th><th>Cashier</th><th>Opened</th><th>Closed</th><th>Expected</th><th>Counted</th><th>Variance</th><th>Status</th></tr></thead><tbody><?php foreach($shifts as $s):?><tr><td><?=e($s['shift_number'])?></td><td><?=e($s['full_name'])?></td><td><?=e($s['opened_at'])?></td><td><?=e($s['closed_at']??'—')?></td><td><?=number_format((float)$s['expected_cash'],2)?></td><td><?= $s['counted_cash']===null?'—':number_format((float)$s['counted_cash'],2)?></td><td><?= $s['variance']===null?'—':number_format((float)$s['variance'],2)?></td><td><?=e($s['status'])?></td></tr><?php endforeach;?></tbody></table><p class="muted">Expected cash currently includes opening float and completed Cash POS sales by the cashier during the shift. Later customer collections, cash refunds and cash paid-outs must be reconciled separately before production use.</p></section>
<?php endif;?>
<?php if($tab==='stocktaking'&&$canStock):?>
<section class="lc-panel"><h2>Physical stock count</h2><?php if($canStockCreate):?><form method="post" class="lc-form"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="tab" value="stocktaking"><input type="hidden" name="action" value="create_count"><label>Count title<input name="title" required placeholder="e.g. November full stock count"></label><button class="lc-btn">Start new count</button></form><?php endif;?></section>
<?php if($activeCount&&$countItems):?><section class="lc-panel"><h2>Count sheet #<?=number_format($activeCount)?></h2><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="tab" value="stocktaking"><input type="hidden" name="action" value="save_count"><input type="hidden" name="count_id" value="<?=$activeCount?>"><table class="lc-table"><thead><tr><th>Product</th><th>SKU</th><th>System quantity</th><th>Physical quantity</th><th>Variance</th></tr></thead><tbody><?php foreach($countItems as $ci):?><tr><td><?=e($ci['product_name'])?></td><td><?=e($ci['sku']??'—')?></td><td><?=number_format((int)$ci['system_quantity'])?></td><td><input type="number" min="0" step="1" name="counted[<?=(int)$ci['id']?>]" value="<?= $ci['counted_quantity']===null?'':(int)$ci['counted_quantity']?>"></td><td><?= $ci['variance']===null?'—':number_format((int)$ci['variance'])?></td></tr><?php endforeach;?></tbody></table><p><button class="lc-btn">Save physical counts</button></p></form><?php if($canStockApprove):?><form method="post" onsubmit="return confirm('Approve this count and post all entered variances to stock?')"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="tab" value="stocktaking"><input type="hidden" name="action" value="approve_count"><input type="hidden" name="count_id" value="<?=$activeCount?>"><button class="lc-btn">Approve & post variances</button></form><?php endif;?></section><?php endif;?>
<section class="lc-panel"><h2>Stock count register</h2><table class="lc-table"><thead><tr><th>Count</th><th>Title</th><th>Date</th><th>Created by</th><th>Status</th></tr></thead><tbody><?php foreach($counts as $c):?><tr><td><?=e($c['count_number'])?></td><td><?=e($c['title'])?></td><td><?=e($c['count_date'])?></td><td><?=e($c['full_name'])?></td><td><?=e($c['status'])?></td></tr><?php endforeach;?></tbody></table></section>
<?php endif;?>
<?php if($tab==='audit'&&$canAudit):?><section class="lc-panel"><h2>Audit trail (latest 100 events)</h2><table class="lc-table"><thead><tr><th>Date</th><th>User</th><th>Action</th><th>Module</th><th>Record</th><th>Description</th><th>IP</th></tr></thead><tbody><?php foreach($audit as $a):?><tr><td><?=e($a['created_at'])?></td><td><?=e($a['full_name']??'System')?></td><td><?=e($a['action'])?></td><td><?=e($a['module_key'])?></td><td><?=e($a['record_type']??'')?> <?=e((string)($a['record_id']??''))?></td><td><?=e($a['description'])?></td><td><?=e($a['ip_address']??'—')?></td></tr><?php endforeach;?></tbody></table><p class="muted">This register captures events generated by the new launch-control workflows. Existing historical activity_logs are not automatically copied into this table.</p></section><?php endif;?>
<?php if($tab==='etims'&&$canEtims):?>
<section class="lc-panel"><h2>eTIMS invoice queue</h2><p class="muted">Prepare completed POS invoices for the KRA integration. Queueing is not the same as submitting to KRA.</p><?php if($canEtimsCreate):?><form method="post" class="lc-form"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="tab" value="etims"><input type="hidden" name="action" value="queue_etims"><label>Completed sale ID<input type="number" name="sale_id" min="1" required></label><button class="lc-btn">Queue invoice</button></form><?php endif;?><table class="lc-table"><thead><tr><th>Invoice</th><th>Sale ID</th><th>Amount</th><th>Status</th><th>KRA invoice</th><th>Queued</th></tr></thead><tbody><?php foreach($etims as $d):?><tr><td><?=e($d['invoice_number'])?></td><td><?=number_format((int)$d['sale_id'])?></td><td>KES <?=number_format((float)$d['total_amount'],2)?></td><td><?=e($d['status'])?></td><td><?=e($d['kra_invoice_number']??'—')?></td><td><?=e($d['created_at'])?></td></tr><?php endforeach;?></tbody></table><p class="muted">Live eTIMS transmission, signing, QR code and KRA response handling are not active in this build.</p></section>
<?php endif;?>
